+    expect(resolvePackagedWindowTitle(adHoc, KD)).toBe("KnowDesign");
+    expect(resolvePackagedWindowTitle({ appVersion: "0.10.0-prerelease.1", namespace: "x" }, KD)).toBe(
+      "KnowDesign Prerelease",
