+  const config = {
+    namespaceBaseRoot: "/tmp/ns",
+    namespace: "release",
+  } as unknown as PackagedConfig;
+
+  function failure(env: Record<string, string>): PackagedPathAccessError {
+    for (const [k, v] of Object.entries(env)) vi.stubEnv(k, v);
